// Turns the sheet, whatever its columns are called, into a clean list of leads to work on in this run.
// New leads get a first email, leads already contacted are checked for a follow-up.
const settings = $('Outreach Settings').first().json;
const map = $input.first().json.output || {};
const rows = $('Read Leads').all().map((i) => i.json).filter((r) => r && r.row_number);

const OWN = ['Outreach Status', 'Outreach Date', 'Outreach Subject', 'Outreach Email', 'Follow-up Subject', 'Follow-up Email', 'Follow-up Date', 'Outreach Notes'];
const FREE_MAIL = ['gmail.', 'googlemail.', 'yahoo.', 'hotmail.', 'outlook.', 'live.', 'icloud.', 'aol.', 'proton.', 'protonmail.', 'msn.', 'me.com', 'gmx.'];
const EMAIL = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i;
const text = (v) => String(v ?? '').trim();
const columns = (key) => (Array.isArray(map[key]) ? map[key] : []).filter((c) => !OWN.includes(c));
const pick = (row, key) => { for (const c of columns(key)) if (text(row[c])) return text(row[c]); return ''; };
const mapped = new Set(['email', 'first_name', 'full_name', 'company', 'website', 'role'].flatMap(columns));

const lead = (row) => {
  let email = (pick(row, 'email').match(EMAIL) || [''])[0];
  if (!email) {
    // No email column recognized: take the first cell that contains an email address.
    const cell = Object.entries(row).find(([k, v]) => !OWN.includes(k) && EMAIL.test(text(v)));
    email = cell ? text(cell[1]).match(EMAIL)[0] : '';
  }
  email = email.toLowerCase();
  let first = (pick(row, 'first_name') || pick(row, 'full_name')).split(/\s+/)[0] || '';
  if (first && (first === first.toUpperCase() || first === first.toLowerCase())) first = first[0].toUpperCase() + first.slice(1).toLowerCase();
  let website = pick(row, 'website');
  const domain = email.split('@')[1] || '';
  if (!website && domain && !FREE_MAIL.some((f) => domain.startsWith(f) || domain === f)) website = domain;
  if (website && !/^https?:\/\//i.test(website)) website = 'https://' + website;
  const details = {};
  for (const [k, v] of Object.entries(row)) {
    if (k !== 'row_number' && !OWN.includes(k) && !mapped.has(k) && text(v)) details[k] = text(v).slice(0, 400);
  }
  return { row_number: row.row_number, email, first_name: first, company: pick(row, 'company'), role: pick(row, 'role'), website, details };
};

const limit = Math.max(0, Number(settings.emails_per_run) || 0);
const waitDays = Number(settings.follow_up_after_days) || 0;
const today = $now.toFormat('yyyy-MM-dd HH:mm');
const seen = new Set();
const marks = [], followUps = [], firsts = [];

for (const row of rows) {
  const l = lead(row);
  const status = text(row['Outreach Status']);
  const duplicate = l.email && seen.has(l.email);
  if (l.email) seen.add(l.email);

  if (!status) {
    const hasData = Object.entries(row).some(([k, v]) => k !== 'row_number' && text(v));
    if (!hasData) continue;
    if (!l.email) marks.push({ task: 'mark', action: 'none', row: { row_number: l.row_number, 'Outreach Status': 'No email', 'Outreach Date': today } });
    else if (duplicate) marks.push({ task: 'mark', action: 'none', row: { row_number: l.row_number, 'Outreach Status': 'Duplicate', 'Outreach Date': today } });
    else firsts.push({ task: 'first', ...l });
    continue;
  }

  const sent = DateTime.fromFormat(text(row['Outreach Date']), 'yyyy-MM-dd HH:mm', { zone: $now.zone });
  const waiting = ['sent', 'drafted'].includes(status.toLowerCase());
  if (waitDays > 0 && waiting && l.email && sent.isValid && sent <= $now.minus({ days: waitDays }) && text(row['Follow-up Email'])) {
    followUps.push({
      task: 'followup', ...l, status,
      sent_day: sent.minus({ days: 1 }).toFormat('yyyy/MM/dd'),
      follow_up_subject: text(row['Follow-up Subject']) || text(row['Outreach Subject']),
      follow_up_body: text(row['Follow-up Email']).replace(/\s*\/\/\s*/g, '\n\n'),   // " // " in the sheet is a paragraph break
    });
  }
}

// Follow-ups go first, then new leads, never more than the limit per run.
const work = [...followUps, ...firsts].slice(0, limit);
return [...marks, ...work].map((json) => ({ json }));

// Adds what the lead's website says to each lead. A missing or blocked website is fine:
// the email is then written from the sheet only.
const leads = $('Pick Leads').all().map((i) => i.json).filter((l) => l.task === 'first');
const pages = $input.all();

const decode = (s) => s
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
  .replace(/&#39;|&apos;|&#x27;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const pick = (html, ...patterns) => {
  for (const re of patterns) { const m = html.match(re); if (m && m[1]) return decode(m[1].trim()); }
  return '';
};

return leads.map((lead, i) => {
  const res = (pages[i] && pages[i].json) || {};
  const html = !res.error && typeof res.data === 'string' ? res.data : '';
  const text = decode(html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ').replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim().slice(0, 4000);
  return {
    json: {
      ...lead,
      website_ok: text.length > 100,
      website_title: pick(html, /<title[^>]*>([\s\S]*?)<\/title>/i).slice(0, 200),
      website_description: pick(html,
        /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i,
        /<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i,
        /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i).slice(0, 400),
      website_text: text.length > 100 ? text : '',
    },
    pairedItem: { item: i },
  };
});

