// ---- The quality gate. These are fixed rules, checked without AI. ----
const settings = $('Outreach Settings').first().json;
const words = (s) => String(s || '').trim().split(/\s+/).filter(Boolean).length;
const BANNED = ['hope this email finds you', 'hope this finds you', 'hope you are doing well', "hope you're doing well", 'i came across', 'i stumbled upon',
  'reaching out because', 'touch base', 'synergy', 'cutting-edge', 'game-changer', 'game changer', 'revolutionize', 'unlock', 'leverage', 'in today\'s',
  'espero que te encuentres bien', 'espero que este correo', 'espero que estés bien', 'me pongo en contacto', 'soluciones innovadoras'];

function findIssues(email, lead) {
  const issues = [];
  const subject = String(email.subject || '').trim(), body = String(email.body || '').trim();
  const fSubject = String(email.follow_up_subject || '').trim(), fBody = String(email.follow_up_body || '').trim();
  const all = [subject, body, fSubject, fBody].join('\n');
  const low = all.toLowerCase();

  if (!subject) issues.push('The subject is empty.');
  if (words(subject) > 7 || subject.length > 60) issues.push('The subject is too long: use 2 to 5 words.');
  if (/\bquick\b|\brápid[ao]\b|!/i.test(subject + ' ' + fSubject)) issues.push('The subject sounds like mass outreach: no "quick", no exclamation marks.');
  if (words(body) < 40) issues.push(`The email is too short (${words(body)} words): it needs the opener, who I am, the offer and the ask.`);
  if (words(body) > 170) issues.push(`The email is too long (${words(body)} words): keep it under 150.`);
  if (/(https?:\/\/|www\.)/i.test(all)) issues.push('Remove every link or URL.');
  if (/\[[^\]]*\]|\{\{|\}\}|<[^>]+>/.test(all)) issues.push('There is a placeholder in brackets: write the real text or leave it out.');
  if (/[—–]/.test(all)) issues.push('Remove the long dashes: use commas or periods.');
  if (/\p{Extended_Pictographic}/u.test(all)) issues.push('Remove the emojis.');
  if (/\*\*|^#+\s|^\s*[-*•]\s/m.test(body)) issues.push('Remove bold, headings and bullet lists: plain sentences only.');
  if ((body.match(/!/g) || []).length > 1) issues.push('Use at most one exclamation mark.');
  if (!body.includes('?')) issues.push('The email has no question: end with one clear ask.');
  for (const p of BANNED) if (low.includes(p)) issues.push(`Remove the phrase "${p}".`);
  if (/\b(inc|llc|ltd|corp|gmbh|s\.a\.|s\.l\.)\b\.?/i.test(body)) issues.push('Write the company name the way people say it, without Inc, LLC, Ltd or similar.');
  if (lead.first_name && !body.slice(0, 80).toLowerCase().includes(lead.first_name.toLowerCase())) issues.push(`Greet the lead by first name (${lead.first_name}) in the first line.`);
  const opener = body.split(/\n\s*\n/).slice(0, 2).join(' ').replace(/^[^,\n]{0,40},\s*/, '');
  if (/^(i work with|i help|i recently|i partner|we |trabajo con|ayudo a|ayudamos)/i.test(opener.trim())) issues.push('The opener talks about the sender: open with an observation about the lead and their business.');
  if (!fBody) issues.push('The follow-up is empty.');
  if (words(fBody) > 60) issues.push(`The follow-up is too long (${words(fBody)} words): 1 to 3 short sentences.`);
  if (/^\s*(re|fwd?|rv)\s*:/i.test(subject) || /^\s*(re|fwd?|rv)\s*:/i.test(fSubject)) issues.push('A subject must not start with "Re:" or "Fwd:": this is not a reply.');
  if (fSubject && fSubject.toLowerCase() === subject.toLowerCase()) issues.push('The follow-up needs a different subject line.');
  return issues;
}

// One standard item for the outbox: what to do, what to send and what to write in the sheet.
// In the sheet every email sits on one line: paragraph breaks are written as " // ".
const oneLine = (s) => String(s || '').trim().replace(/\s*\n+\s*/g, ' // ');

function outboxItem(lead, email, attempt) {
  const issues = findIssues(email, lead);
  const mode = String(settings.send_mode || 'draft').trim().toLowerCase() === 'send' ? 'send' : 'draft';
  const ok = issues.length === 0;
  return {
    action: ok ? mode : 'draft',
    to: lead.email,
    subject: String(email.subject || '').trim(),
    body: String(email.body || '').trim(),
    issues, attempt, lead, email,
    row: {
      row_number: lead.row_number,
      'Outreach Status': !ok ? 'Needs review' : mode === 'send' ? 'Sent' : 'Drafted',
      'Outreach Date': $now.toFormat('yyyy-MM-dd HH:mm'),
      'Outreach Subject': String(email.subject || '').trim(),
      'Outreach Email': oneLine(email.body),
      'Follow-up Subject': String(email.follow_up_subject || '').trim(),
      'Follow-up Email': oneLine(email.follow_up_body),
      'Outreach Notes': ok ? 'Opener based on: ' + String(email.opener_based_on || 'not stated') : 'Check the draft before sending: ' + issues.join(' '),
    },
  };
}
// Checks every email the AI wrote against the writing rules.
const leads = $('Lead Research').all();
return $input.all().map((item, i) => ({
  json: outboxItem(leads[i].json, item.json.output || {}, 1),
  pairedItem: { item: i },
}));

