  json: outboxItem(before[i].json.lead, item.json.output || {}, 2),
  pairedItem: { item: i },
}));

// For every lead waiting for a follow-up: did they reply? Was the first email really sent?
// A lead who replied is marked "Replied" and never gets the follow-up.
const settings = $('Outreach Settings').first().json;
const mode = String(settings.send_mode || 'draft').trim().toLowerCase() === 'send' ? 'send' : 'draft';
const leads = $('Pick Leads').all().map((i) => i.json).filter((l) => l.task === 'followup');
const messages = $input.all().map((i) => i.json).filter((m) => m && m.id);
const field = (m, name) => {
  const v = m[name] ?? m[name.toLowerCase()] ?? '';
  return (typeof v === 'string' ? v : JSON.stringify(v)).toLowerCase();
};
const today = $now.toFormat('yyyy-MM-dd HH:mm');
const out = [];

for (const lead of leads) {
  const replied = messages.some((m) => field(m, 'From').includes(lead.email));
  const wasSent = lead.status.toLowerCase() === 'sent' || messages.some((m) => field(m, 'To').includes(lead.email) && !field(m, 'From').includes(lead.email));
  if (replied) {
    out.push({ action: 'none', row: { row_number: lead.row_number, 'Outreach Status': 'Replied', 'Follow-up Date': today } });
  } else if (wasSent) {
    out.push({
      action: mode, to: lead.email, subject: lead.follow_up_subject, body: lead.follow_up_body,
      row: { row_number: lead.row_number, 'Outreach Status': mode === 'send' ? 'Followed up' : 'Follow-up drafted', 'Follow-up Date': today },
    });
  }
  // A draft that was never sent gets no follow-up.
}
return out.map((json) => ({ json }));
